                    for (int k = 0; k < (int)r.n; k++) il.Add((xs[k] != 0));
                    break;
                }
                case OP_ADD when outer == 1 && inner == 5:
                {
                    var xs = (int*)body; var e = t.Batches[(int)r.token]; var il = e.Statuses;
                    for (int k = 0; k < (int)r.n; k++) il.Add((TaskStatus)xs[k]);
