    public int Fill(DualResponse src) { Go(src, false, false, out _, out _); return 0; }
    public void Encode(DualResponse src, out byte* p, out int len) { int rc = Go(src, false, true, out p, out len); if (rc < 0) throw new InvalidOperationException($"core encode failed: {rc}"); }
    public void EncodeU(DualResponse src, out byte* p, out int len) { int rc = Go(src, true, true, out p, out len); if (rc < 0) throw new InvalidOperationException($"core encode failed: {rc}"); }
    public int TryEncode(DualResponse src, bool retain, out byte* p, out int len) => Go(src, retain, true, out p, out len);
    public byte[] EncodeToArray(DualResponse src, bool retain = false)
    {
        int rc = Go(src, retain, true, out byte* p, out int len);
        if (rc < 0) throw new InvalidOperationException($"core encode failed: {rc}");
        var a = new byte[len];
        new ReadOnlySpan<byte>(p, len).CopyTo(a);
        return a;
    }

    private int Go(DualResponse src, bool retain, bool call, out byte* outPtr, out int outLen)
    {
        outPtr = null; outLen = 0;
        Abi.ak_enc_reset(_ctx);
        _st.Reset();
        _run->Chunk = Chunk;
        _run->Retain = retain ? 1 : 0;
        {
            var lst = src.Left;
            int n = lst == null ? 0 : lst.Count;
            _run->N_left = n;
            Arr.Ensure(ref _run->S_left, ref _cap_left, n, Math.Max(sizeof(ak_efix_Pair), sizeof(ak_ufix_Pair)));
            for (int i = 0; i < n; i++)
            {
                if (retain) G.U_Pair(ref ((ak_ufix_Pair*)_run->S_left)[i], lst[i], _st);
                else G.E_Pair(ref ((ak_efix_Pair*)_run->S_left)[i], lst[i], _st);
            }
        }
        {
            var lst = src.Right;
            int n = lst == null ? 0 : lst.Count;
            _run->N_right = n;
            Arr.Ensure(ref _run->S_right, ref _cap_right, n, Math.Max(sizeof(ak_efix_Pair), sizeof(ak_ufix_Pair)));
            for (int i = 0; i < n; i++)
            {
                if (retain) G.U_Pair(ref ((ak_ufix_Pair*)_run->S_right)[i], lst[i], _st);
                else G.E_Pair(ref ((ak_efix_Pair*)_run->S_right)[i], lst[i], _st);
            }
        }
        var vt = new ak_evt_DualResponse
        {
            loop_left = &Loop_left,
            loop_right = &Loop_right,
        };
        nint rc;
        if (retain)
        {
            var fix = new ak_ufix_DualResponse();
            G.U_DualResponse(ref fix, src, _st);
            if (!call) return 0;
            _fwd++;
            rc = Abi.ak_uencode_DualResponse(_run, _ctx, &vt, &fix);
        }
        else
        {
            var fix = new ak_efix_DualResponse();
            G.E_DualResponse(ref fix, src, _st);
            if (!call) return 0;
            _fwd++;
            rc = Abi.ak_encode_DualResponse(_run, _ctx, &vt, &fix);
        }
        if (rc < 0) return (int)rc;
        byte* bp; nuint blen;
        int tk = Abi.ak_enc_take(_ctx, &bp, &blen);
        if (tk != 0) return tk;
        outPtr = bp; outLen = (int)blen;
        return 0;
    }

    [StructLayout(LayoutKind.Sequential)]
    private struct DecRun { public IntPtr Target; public byte* Buf; public IntPtr Pending; }

    private static DualResponse Tgt(void* obj) => (DualResponse)GCHandle.FromIntPtr(((DecRun*)obj)->Target).Target;

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void ApplyRoot(IntPtr ctx, void* obj, ak_dfix_DualResponse* fix)
    {
        _rev++;
        try { G.D_DualResponse(ref *fix, Tgt(obj), ((DecRun*)obj)->Buf); }
        catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); }
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void Add_left(IntPtr ctx, void* obj, long token, ak_dfix_Pair* xs, int n)
    {
        _rev++;
        try
        {
            byte* b = ((DecRun*)obj)->Buf;
            var lst = Tgt(obj).Left;
            for (int i = 0; i < n; i++) { var x = new Pair(); G.D_Pair(ref xs[i], x, b); lst.Add(x); }
        }
        catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); }
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static void Add_right(IntPtr ctx, void* obj, long token, ak_dfix_Pair* xs, int n)
    {
        _rev++;
        try
        {
            byte* b = ((DecRun*)obj)->Buf;
            var lst = Tgt(obj).Right;
            for (int i = 0; i < n; i++) { var x = new Pair(); G.D_Pair(ref xs[i], x, b); lst.Add(x); }
        }
        catch { Abi.ak_fail(ctx, Abi.AK_ERR_HOST, null, 0); }
    }

    private static readonly byte[] One = new byte[1];

    public DualResponse Decode(byte[] src, int len) { int rc = TryDecode(src, len, false, out var t); if (rc < 0) throw new InvalidOperationException($"core decode failed: {rc}"); return t; }
    public DualResponse DecodeU(byte[] src, int len) { int rc = TryDecode(src, len, true, out var t); if (rc < 0) throw new InvalidOperationException($"core decode failed: {rc}"); return t; }

    /// The core's code (< 0) on failure; the output is then unspecified and discarded (R-G6).
    public int TryDecode(byte[] src, int len, bool retain, out DualResponse result)
    {
        result = null;
        if (_dctx == IntPtr.Zero)
        {
            _dctx = Abi.ak_dec_ctx_new();
            _drun = (DecRun*)NativeMemory.AllocZeroed((nuint)sizeof(DecRun));
        }
        Abi.ak_dec_err_reset(_dctx);
        var target = new DualResponse();
        var pend = retain ? new List<(int, long, byte[])>() : null;
        var h = GCHandle.Alloc(target);
        var hp = retain ? GCHandle.Alloc(pend) : default;
        int rc;
        try
        {
            fixed (byte* b0 = src)
            fixed (byte* one = One)
            {
                // (NULL, 0) is never handed to the core: an empty buffer is a valid pointer and 0.
                byte* b = len == 0 ? one : b0;
                _drun->Target = GCHandle.ToIntPtr(h);
                _drun->Buf = b;
                _drun->Pending = retain ? GCHandle.ToIntPtr(hp) : IntPtr.Zero;
                var vt = new ak_dvt_DualResponse
                {
                    apply = &ApplyRoot,
                    add_left = &Add_left,
                    add_right = &Add_right,
                };
                _fwd++;
                rc = Abi.ak_decode_DualResponse(_dctx, _drun, b, (nuint)len, &vt);
                if (rc >= 0) { int he = Abi.ak_dec_err(_dctx); if (he != 0) rc = he; }
            }
        }
        finally { h.Free(); if (retain) hp.Free(); }
        if (rc < 0) return rc;
        if (retain)
        {
            // Applied after the decode: a capture may flush before the run that
            // carries the element it belongs to.
            foreach (var (slot, token, bytes) in pend)
            {
                switch (slot)
                {
                    case 0: target.UnknownFields = W.Append(target.UnknownFields, bytes, 0, bytes.Length); break;
                    case 1: { var l = target.Left; if (l != null && token >= 0 && token < l.Count) { var e = l[(int)token]; e.UnknownFields = W.Append(e.UnknownFields, bytes, 0, bytes.Length); } break; }
                    case 2: { var l = target.Right; if (l != null && token >= 0 && token < l.Count) { var e = l[(int)token]; e.UnknownFields = W.Append(e.UnknownFields, bytes, 0, bytes.Length); } break; }
                    default: break;   // a map entry has no bag
                }
            }
        }
        result = target;
        return 0;
    }

    /// ABI v1 7.1's PULL family: parse into the context's record stream (no reverse
    /// call), then replay it with the same group readers the push callbacks use.
    public DualResponse Pull(byte[] src, int len)
    {
        if (_dctx == IntPtr.Zero)
        {
            _dctx = Abi.ak_dec_ctx_new();
            _drun = (DecRun*)NativeMemory.AllocZeroed((nuint)sizeof(DecRun));
        }
        var t = new DualResponse();
        fixed (byte* b0 = src)
        fixed (byte* one = One)
        {
            byte* b = len == 0 ? one : b0;
            _fwd++;
            int rc = Abi.ak_parse_DualResponse(_dctx, b, (nuint)len);
            if (rc < 0) throw new InvalidOperationException($"core parse failed: {rc}");
            byte* recs; nuint rlen;
            _fwd++;
            int pr = Abi.ak_bdr_ptr(_dctx, &recs, &rlen);
            if (pr != 0) throw new InvalidOperationException($"ak_bdr_ptr failed: {pr}");
            Replay(t, b, recs, (int)rlen);
        }
        return t;
    }

    private const uint OP_APPLY = 1, OP_ADD = 2, OP_NEW = 3, OP_APPLY_ELEM = 4;   // ak_bdr_rec.op
    private static void Replay(DualResponse t, byte* b, byte* p, int len)
    {
        int at = 0;
        while (len - at >= sizeof(ak_bdr_rec))
        {
            ref var r = ref *(ak_bdr_rec*)(p + at);
            byte* body = p + at + sizeof(ak_bdr_rec);
            at += sizeof(ak_bdr_rec) + (int)r.bytes;
            uint outer = r.slot >> 16, inner = r.slot & 0xFFFF;
            switch (r.op)
            {
                case OP_APPLY: G.D_DualResponse(ref *(ak_dfix_DualResponse*)body, t, b); break;
                case OP_ADD when outer == 0 && inner == 1:   // a root-level run
                {
                    var xs = (ak_dfix_Pair*)body; var lst = t.Left;
                    for (int i = 0; i < (int)r.n; i++) { var x = new Pair(); G.D_Pair(ref xs[i], x, b); lst.Add(x); }
                    break;
                }
                case OP_ADD when outer == 0 && inner == 2:   // a root-level run
                {
                    var xs = (ak_dfix_Pair*)body; var lst = t.Right;
                    for (int i = 0; i < (int)r.n; i++) { var x = new Pair(); G.D_Pair(ref xs[i], x, b); lst.Add(x); }
                    break;
                }
                default: break;
            }
        }
    }

    public long PullFootprint() => _dctx == IntPtr.Zero ? 0 : (long)Abi.ak_bdr_footprint(_dctx);
    public AkCounters EncCounters() { AkCounters c; Abi.ak_enc_counters(_ctx, &c); return c; }
    public void EncCountersReset() => Abi.ak_enc_counters_reset(_ctx);
    public AkCounters DecCounters() { AkCounters c; if (_dctx == IntPtr.Zero) return default; Abi.ak_dec_counters(_dctx, &c); return c; }
    public void DecCountersReset() { if (_dctx != IntPtr.Zero) Abi.ak_dec_counters_reset(_dctx); }

    public void Dispose()
    {
        if (_ctx != IntPtr.Zero) { Abi.ak_enc_ctx_free(_ctx); _ctx = IntPtr.Zero; }
        if (_dctx != IntPtr.Zero) { Abi.ak_dec_ctx_free(_dctx); _dctx = IntPtr.Zero; }
        _st.Dispose();
        if (_run != null)
        {
            NativeMemory.Free(_run->S_left);
            NativeMemory.Free(_run->S_right);
            NativeMemory.Free(_run); _run = null;
        }
        if (_drun != null) { NativeMemory.Free(_drun); _drun = null; }
    }
}

#endif
